// The talk's knobs: intensity, falloff, tangent falloff (retro, then diffuse Fresnel), the smooth
// terminator's o and p, Proxima's GGX alpha and the alpha_s reading (0 radians, 1 angle / 90, 2 cosines).
struct SlideModel {
  const char* name;
  double retro;
  double retro_falloff;
  double retro_tangent_falloff;
  double fresnel;
  double fresnel_falloff;
  double fresnel_tangent_falloff;
  double terminator;
  double terminator_length;
  double proxima_alpha;
  int alpha_s_reading;
};

